import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor cute_sigmoid(torch::Tensor x);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

__global__ void cute_sigmoid_kernel(const float4* __restrict__ in,
                                     float4* __restrict__ out,
                                     int N4)
{
    Tensor gIn  = make_tensor(make_gmem_ptr(in),  make_shape(N4), make_stride(Int<1>{}));
    Tensor gOut = make_tensor(make_gmem_ptr(out), make_shape(N4), make_stride(Int<1>{}));

    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int stride = gridDim.x * blockDim.x;

    for (int i = idx; i < N4; i += stride) {
        float4 v = gIn(i);
        float4 r;
        r.x = __fdividef(1.0f, 1.0f + __expf(-v.x));
        r.y = __fdividef(1.0f, 1.0f + __expf(-v.y));
        r.z = __fdividef(1.0f, 1.0f + __expf(-v.z));
        r.w = __fdividef(1.0f, 1.0f + __expf(-v.w));
        gOut(i) = r;
    }
}

__global__ void cute_sigmoid_kernel_scalar(const float* __restrict__ in,
                                            float* __restrict__ out,
                                            int N)
{
    Tensor gIn  = make_tensor(make_gmem_ptr(in),  make_shape(N), make_stride(Int<1>{}));
    Tensor gOut = make_tensor(make_gmem_ptr(out), make_shape(N), make_stride(Int<1>{}));

    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int stride = gridDim.x * blockDim.x;

    for (int i = idx; i < N; i += stride) {
        float v = gIn(i);
        gOut(i) = __fdividef(1.0f, 1.0f + __expf(-v));
    }
}

torch::Tensor cute_sigmoid(torch::Tensor x) {
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "Expect float32 tensor");

    auto x_c = x.contiguous();
    auto out = torch::empty_like(x_c);

    int64_t total = x_c.numel();
    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

    const int threads = 256;

    if (total % 4 == 0) {
        int N4 = (int)(total / 4);
        int blocks = (N4 + threads - 1) / threads;
        if (blocks > 65535) blocks = 65535;
        cute_sigmoid_kernel<<<blocks, threads, 0, stream>>>(
            reinterpret_cast<const float4*>(x_c.data_ptr<float>()),
            reinterpret_cast<float4*>(out.data_ptr<float>()),
            N4);
    } else {
        int N = (int)total;
        int blocks = (N + threads - 1) / threads;
        if (blocks > 65535) blocks = 65535;
        cute_sigmoid_kernel_scalar<<<blocks, threads, 0, stream>>>(
            x_c.data_ptr<float>(), out.data_ptr<float>(), N);
    }

    TORCH_CHECK(cudaGetLastError() == cudaSuccess, "CUTE sigmoid launch failed");
    return out;
}
"""

cute_ext = load_inline(
    name="cute_sigmoid_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["cute_sigmoid"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/workspace/cutegen_test/cutegen/cutlass/include"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Model that performs a Sigmoid activation using a custom CUTE kernel.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self._ext = cute_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.cute_sigmoid(x)


batch_size = 4096
dim = 131072


def get_inputs():
    x = torch.rand(batch_size, dim).cuda()
    return [x]


def get_init_inputs():
    return []

